<template>
  <div>
    <router-link class="back-link" :to="workspacePath"><ArrowLeft :size="16" />返回工作台</router-link>
    <div class="page-header"><div><h1 class="page-title">应用栈</h1><p class="page-subtitle">{{ environment ? `${project?.name} · ${environment.name} · ${environment.namespace}` : '请选择项目与环境后管理组合应用' }}</p></div><div class="page-actions"><button class="btn" :disabled="!environment" @click="openEditor()">新建通用栈</button><button class="btn btn-primary" :disabled="!environment" @click="openKarakeep">使用 Karakeep 预设</button></div></div>
    <div v-if="error" class="k8s-banner k8s-banner-warn section-gap">{{ error }}</div>
    <div v-if="!environment && loaded" class="empty-state"><span class="empty-text">请从工作台选择项目和环境后进入应用栈。</span><router-link class="btn btn-primary" to="/applications">前往工作台</router-link></div>
    <template v-else-if="environment">
      <div v-if="stacks.length" class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>应用栈</th><th>入口应用</th><th>组件应用</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="stack in stacks" :key="stack.id"><td class="cell-primary">{{ stack.name }}<small>{{ stack.description || '未设置说明' }}</small></td><td>{{ stack.spec.entry_application || '-' }}</td><td><div class="component-links"><button v-for="component in stack.spec.components" :key="component.application_name" class="component-link" @click="openApplication(component.application_name)">{{ component.application_name }}</button></div></td><td><span class="badge" :class="stack.enabled ? 'badge-online' : 'badge-offline'">{{ stack.enabled ? '启用' : '停用' }}</span></td><td><div class="btn-group"><button class="btn btn-sm" :disabled="!stack.enabled" @click="openRelease(stack)">发布</button><button class="btn btn-sm" @click="openEditor(stack)">编辑</button><button class="btn btn-sm btn-danger" @click="removeStack(stack)">删除</button></div></td></tr></tbody></table></div></div>
      <div v-else-if="loaded" class="empty-state"><span class="empty-text">当前环境还没有应用栈</span><button class="btn btn-primary" @click="openKarakeep">创建 Karakeep 栈</button></div>
      <section v-for="stack in stacks" :key="`release-${stack.id}`" class="release-section"><div class="section-heading"><div><h2>{{ stack.name }} 发布记录</h2><p>每个组件会生成独立应用和独立发布记录。</p></div></div><div v-if="stack.releases?.length" class="stack-runs"><div v-for="release in stack.releases.slice(0, 3)" :key="release.id" class="run-row"><span class="badge" :class="release.status === 'succeeded' ? 'badge-online' : release.status === 'failed' ? 'badge-danger' : 'badge-deploying'">{{ release.status }}</span><small>{{ release.detail || '处理中' }}</small></div></div><div v-else class="empty-inline">尚未发布</div></section>
    </template>

    <Teleport to="body"><div v-if="showEditor" class="overlay" @click.self="closeEditor"><div class="modal editor-modal"><h2 class="modal-title">{{ editing ? '编辑应用栈' : '新建通用应用栈' }}</h2><form @submit.prevent="saveStack"><div class="form-row"><div class="form-group"><label class="form-label">名称</label><input v-model.trim="form.name" class="form-input" required placeholder="知识库服务" /></div><div class="form-group"><label class="form-label">入口应用</label><select v-model="form.entry_application" class="form-select"><option value="">不设置对外入口</option><option v-for="component in form.components" :key="component.application_name" :value="component.application_name">{{ component.application_name }}</option></select></div></div><div class="form-group"><label class="form-label">说明</label><input v-model.trim="form.description" class="form-input" placeholder="由多个独立服务组成" /></div><div class="component-editor"><div class="component-heading"><label class="form-label">组件应用</label><button type="button" class="btn btn-sm" @click="addComponent">+ 添加组件</button></div><div v-for="(component, index) in form.components" :key="index" class="component-form"><div class="form-row"><div class="form-group"><label class="form-label">应用名称</label><input v-model.trim="component.application_name" class="form-input" required placeholder="search" /></div><div class="form-group"><label class="form-label">镜像地址</label><input v-model.trim="component.image" class="form-input" required placeholder="registry.example.com/search" /></div></div><div class="form-row"><div class="form-group"><label class="form-label">默认版本</label><input v-model.trim="component.version" class="form-input" required placeholder="latest" /></div><div class="form-group"><label class="form-label">容器端口</label><input v-model.number="component.container_port" type="number" min="1" class="form-input" required /></div><div class="form-group"><label class="form-label">副本数</label><input v-model.number="component.replicas" type="number" min="1" class="form-input" required /></div></div><div class="form-row"><div class="form-group"><label class="form-label">ConfigMap 环境变量</label><textarea v-model="component.config_text" class="form-input form-textarea" placeholder="KEY=VALUE"></textarea></div><div class="form-group"><label class="form-label">Secret 环境变量</label><textarea v-model="component.secrets_text" class="form-input form-textarea" placeholder="KEY=VALUE"></textarea></div></div><div class="form-row"><div class="form-group"><label class="form-label">PVC</label><select v-model="component.pvc_name" class="form-select"><option value="">不挂载数据卷</option><option v-for="claim in claims" :key="claim.name" :value="claim.name">{{ claim.name }} · {{ claim.phase }}</option></select></div><div class="form-group"><label class="form-label">挂载路径</label><input v-model.trim="component.mount_path" class="form-input" :disabled="!component.pvc_name" placeholder="/data" /></div><button type="button" class="icon-button danger-action" title="移除组件" :disabled="form.components.length === 1" @click="removeComponent(index)"><Trash2 :size="16" /></button></div></div></div><label class="check-row"><input v-model="form.enabled" type="checkbox" /> 启用此应用栈</label><div class="modal-actions"><button type="button" class="btn" @click="closeEditor">取消</button><button class="btn btn-primary" :disabled="saving">{{ saving ? '保存中...' : '保存应用栈' }}</button></div></form></div></div></Teleport>
    <Teleport to="body"><div v-if="showKarakeep" class="overlay" @click.self="showKarakeep = false"><div class="modal"><h2 class="modal-title">创建 Karakeep 应用栈</h2><form @submit.prevent="saveKarakeep"><div class="form-group"><label class="form-label">应用栈名称</label><input v-model.trim="karakeep.name" class="form-input" required /></div><div class="form-row"><div class="form-group"><label class="form-label">Karakeep PVC</label><select v-model="karakeep.data_pvc" class="form-select" required><option value="" disabled>选择数据卷</option><option v-for="claim in claims" :key="claim.name" :value="claim.name">{{ claim.name }} · {{ claim.phase }}</option></select></div><div class="form-group"><label class="form-label">Meilisearch PVC</label><select v-model="karakeep.meilisearch_pvc" class="form-select" required><option value="" disabled>选择数据卷</option><option v-for="claim in claims" :key="claim.name" :value="claim.name">{{ claim.name }} · {{ claim.phase }}</option></select></div></div><div class="form-row"><div class="form-group"><label class="form-label">NEXTAUTH_SECRET</label><input v-model="karakeep.nextauth_secret" type="password" class="form-input" required /></div><div class="form-group"><label class="form-label">MEILI_MASTER_KEY</label><input v-model="karakeep.meili_master_key" type="password" class="form-input" required /></div></div><div class="modal-actions"><button type="button" class="btn" @click="showKarakeep = false">取消</button><button class="btn btn-primary" :disabled="saving">{{ saving ? '保存中...' : '创建应用栈' }}</button></div></form></div></div></Teleport>
    <Teleport to="body"><div v-if="releaseTarget" class="overlay" @click.self="releaseTarget = null"><div class="modal"><h2 class="modal-title">发布 {{ releaseTarget.name }}</h2><form @submit.prevent="publish"><div v-for="component in releaseTarget.spec.components" :key="component.application_name" class="form-group"><label class="form-label">{{ component.application_name }} 版本</label><input v-model.trim="versions[component.application_name]" class="form-input" required /></div><div class="modal-actions"><button type="button" class="btn" @click="releaseTarget = null">取消</button><button class="btn btn-primary" :disabled="saving">{{ saving ? '创建中...' : '创建发布' }}</button></div></form></div></div></Teleport>
  </div>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, Trash2 } from 'lucide-vue-next'
import { api } from '../api/index.js'

const route = useRoute()
const router = useRouter()
const projects = ref([])
const stacks = ref([])
const claims = ref([])
const applications = ref([])
const loaded = ref(false)
const saving = ref(false)
const error = ref('')
const showEditor = ref(false)
const showKarakeep = ref(false)
const editing = ref(null)
const releaseTarget = ref(null)
const versions = ref({})
const form = ref(blankStack())
const karakeep = ref(blankKarakeep())

const projectID = computed(() => Number(route.query.project_id) || 0)
const environmentID = computed(() => Number(route.query.environment_id) || 0)
const project = computed(() => projects.value.find(item => item.id === projectID.value) || null)
const environment = computed(() => project.value?.environments?.find(item => item.id === environmentID.value) || null)
const workspacePath = computed(() => ({ path: '/applications', query: route.query }))

function blankComponent() { return { application_name: '', image: '', version: 'latest', container_port: 8080, replicas: 1, config_text: '', secrets_text: '', pvc_name: '', mount_path: '/data' } }
function blankStack() { return { name: '', description: '', enabled: true, entry_application: '', components: [blankComponent()] } }
function blankKarakeep() { return { name: 'Karakeep', data_pvc: '', meilisearch_pvc: '', nextauth_secret: '', meili_master_key: '' } }
function linesToMap(value) { return String(value || '').split('\n').map(item => item.trim()).filter(Boolean).reduce((result, line) => { const index = line.indexOf('='); if (index > 0) result[line.slice(0, index).trim()] = line.slice(index + 1); return result }, {}) }
function mapToLines(value) { return Object.entries(value || {}).map(([key, item]) => `${key}=${item || ''}`).join('\n') }
function componentPayload(component) { return { application_name: component.application_name, spec: { image: component.image, version: component.version, container_port: component.container_port, replicas: component.replicas, config: linesToMap(component.config_text), secrets: linesToMap(component.secrets_text), volumes: component.pvc_name ? [{ claim_name: component.pvc_name, mount_path: component.mount_path, read_only: false }] : [], resources: { requests_cpu: '100m', requests_memory: '128Mi', limits_cpu: '500m', limits_memory: '512Mi' }, health: { readiness_enabled: false, liveness_enabled: false }, service: { port: component.container_port, target_port: component.container_port }, endpoint: { exposure: 'cluster' } } } }
function stackPayload() { return { environment_id: environmentID.value, name: form.value.name, description: form.value.description, enabled: form.value.enabled, spec: { entry_application: form.value.entry_application, components: form.value.components.map(componentPayload) } } }
function addComponent() { form.value.components.push(blankComponent()) }
function removeComponent(index) { form.value.components.splice(index, 1) }
function openEditor(stack = null) { editing.value = stack; form.value = stack ? { name: stack.name, description: stack.description || '', enabled: stack.enabled, entry_application: stack.spec.entry_application || '', components: (stack.spec.components || []).map(component => ({ application_name: component.application_name, image: component.spec.image, version: component.spec.version || 'latest', container_port: component.spec.container_port, replicas: component.spec.replicas, config_text: mapToLines(component.spec.config), secrets_text: Object.keys(component.spec.secrets || {}).map(key => `${key}=`).join('\n'), pvc_name: component.spec.volumes?.[0]?.claim_name || '', mount_path: component.spec.volumes?.[0]?.mount_path || '/data' })) } : blankStack(); showEditor.value = true }
function closeEditor() { showEditor.value = false; editing.value = null }
function openKarakeep() { karakeep.value = blankKarakeep(); showKarakeep.value = true }
async function load() { loaded.value = false; error.value = ''; try { projects.value = await api.get('/projects') || []; if (!environment.value) { stacks.value = []; return } const [templates, volumeClaims, apps] = await Promise.all([api.get(`/application-stacks?environment_id=${environmentID.value}`), api.get(`/k8s/persistent-volume-claims?environment_id=${environmentID.value}`), api.get(`/applications?project_id=${projectID.value}&environment_id=${environmentID.value}`)]); stacks.value = await Promise.all((templates || []).map(async stack => ({ ...stack, releases: await api.get(`/application-stacks/${stack.id}/releases`) || [] }))); claims.value = volumeClaims || []; applications.value = apps || [] } catch (e) { error.value = e.message || '加载应用栈失败' } finally { loaded.value = true } }
async function saveStack() { saving.value = true; error.value = ''; try { if (editing.value) await api.put(`/application-stacks/${editing.value.id}`, stackPayload()); else await api.post('/application-stacks', stackPayload()); closeEditor(); await load() } catch (e) { error.value = e.message || '保存应用栈失败' } finally { saving.value = false } }
async function saveKarakeep() { saving.value = true; error.value = ''; try { await api.post('/application-stacks/presets/karakeep', { environment_id: environmentID.value, ...karakeep.value }); showKarakeep.value = false; await load() } catch (e) { error.value = e.message || '创建 Karakeep 应用栈失败' } finally { saving.value = false } }
function openRelease(stack) { releaseTarget.value = stack; versions.value = Object.fromEntries(stack.spec.components.map(component => [component.application_name, component.spec.version || 'latest'])) }
async function publish() { if (!releaseTarget.value) return; saving.value = true; error.value = ''; try { await api.post(`/application-stacks/${releaseTarget.value.id}/releases`, { versions: versions.value }); releaseTarget.value = null; await load() } catch (e) { error.value = e.message || '创建应用栈发布失败' } finally { saving.value = false } }
async function removeStack(stack) { if (!window.confirm(`删除应用栈模板 ${stack.name}？已创建的应用和数据卷不会删除。`)) return; try { await api.delete(`/application-stacks/${stack.id}`); await load() } catch (e) { error.value = e.message || '删除应用栈失败' } }
async function openApplication(name) { const app = applications.value.find(item => item.name === name); if (!app) { error.value = '该组件将在首次发布时创建'; return } await router.push(`/applications/${app.id}`) }

watch(() => [route.query.project_id, route.query.environment_id], load, { immediate: true })
</script>

<style scoped>
.back-link{display:inline-flex;align-items:center;gap:6px;margin-bottom:var(--space-16);color:var(--text-secondary);font-size:13px;font-weight:600;text-decoration:none}.back-link:hover{color:var(--action-primary)}.page-header,.page-actions,.section-heading,.component-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--space-12)}.page-header{margin-bottom:var(--space-20)}.page-subtitle,.section-heading p,.cell-primary small,.empty-inline{margin:4px 0 0;color:var(--text-secondary);font-size:12px}.component-links,.stack-runs{display:flex;flex-wrap:wrap;gap:6px}.component-link{border:1px solid var(--border-muted);border-radius:var(--radius-control);background:var(--surface-subtle);color:var(--action-primary);font:inherit;font-size:11px;cursor:pointer}.component-link:hover{background:var(--surface-hover)}.release-section{padding:var(--space-16) 0;border-top:1px solid var(--border-muted)}.run-row{display:flex;align-items:center;gap:8px}.run-row small{color:var(--text-secondary);font-size:11px}.editor-modal{width:min(780px,calc(100vw - 32px))}.component-editor{display:grid;gap:10px}.component-form{position:relative;padding:12px;border:1px solid var(--border-muted);border-radius:var(--radius-control);background:var(--surface-subtle)}.component-form>.icon-button{position:absolute;right:8px;bottom:8px}.form-textarea{min-height:76px;resize:vertical}.check-row{display:flex;align-items:center;gap:8px;margin:var(--space-12) 0;color:var(--text-secondary);font-size:13px}@media(max-width:640px){.page-header,.page-actions,.section-heading{align-items:stretch;flex-direction:column}.page-actions .btn{width:100%}}
</style>
